// Источник: web-тест .qa/e2e/tests/prayer-history/ph-01-history-grouping-search.spec.ts, план .qa/e2e/specs/prayer-history.md, кейс .qa/tests/prayer-history/PH-01-history-grouping-search.md
// Тикет #6a86f800 · e2197815c212 «פיתוח: היסטוריית תפילות עם חיפוש». Опора: F-43 AC1–AC5 · F-34 · S-26.
// /journey/history → главная → «צפה בהכל». Точные количества строк (100 / все = «סה״כ תפילות») не переносятся:
// Android не отдаёт строки за пределами экрана. Проверяются формат групп/строк, результаты поиска (1 строка / 1 группа), подсказка,
// пустое состояние и исчезновение «טען תפילות קודמות».
import { expect, $$, driver } from '@wdio/globals';
import { byText, byLabel, tapText, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';

const q = (s: string) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
const GROUP = "[א-ת״׳' ]+ · \\d{1,2} [א-ת]+׳?";
const ROW_LABEL = '.+, \\d{2}:\\d{2}(:\\d{2})?';

/** Строки истории: подпись «<молитва>, <евр. дата> · <греч. дата>, HH:mm[:ss]». */
async function rows() {
  const els = driver.isAndroid
    ? await $$(`android=new UiSelector().descriptionMatches("${q(ROW_LABEL)}")`)
    : await $$(`-ios predicate string:name MATCHES "${q(ROW_LABEL)}" OR label MATCHES "${q(ROW_LABEL)}"`);
  const out: string[] = [];
  for (const el of els) {
    if (await el.isDisplayed().catch(() => false)) out.push((await el.getAttribute(driver.isAndroid ? 'content-desc' : 'name')) || '');
  }
  return out;
}
/** Заголовки групп дней «<евр. дата> · <греч. дата>». */
async function groups() {
  const els = driver.isAndroid
    ? await $$(`android=new UiSelector().textMatches("${q(GROUP)}")`)
    : await $$(`-ios predicate string:label MATCHES "${q(GROUP)}"`);
  const out: string[] = [];
  for (const el of els) if (await el.isDisplayed().catch(() => false)) out.push(await el.getText());
  return out;
}
async function search(text: string) {
  const field = await byLabel('חיפוש');
  await field.clearValue();
  if (text) await field.setValue(text);
}
async function until(fn: () => Promise<boolean>, msg: string) {
  await driver.waitUntil(fn, { timeoutMsg: msg });
}

describe('История молитв', () => {
  afterEach(async () => { await toHome(); });

  it('PH-01 «היסטוריית התפילות שלי»: группировка по дням, HH:mm, поиск, подгрузка #6a86f800 @prod-safe', async () => {
    // 1. Главная → «צפה בהכל» → «היסטוריית התפילות שלי».
    await scrollToText('צפה בהכל');
    await tapText('צפה בהכל');
    await (await byText('היסטוריית התפילות שלי')).waitForDisplayed({ timeout: 20000 });
    expect(await byText('היסטוריית תפילות שלי').isExisting()).toBe(false);   // старое имя (#9e970625 / #56d002bd, עבר QA 25.10)
    await until(async () => (await rows()).length > 0, 'Нет строк истории');
    expect((await groups())[0]).toMatch(/^[א-ת״׳' ]+ · \d{1,2} [א-ת]+׳?$/);
    expect((await rows())[0]).toMatch(/^[א-ת ()]+, .+ · .+, \d{2}:\d{2}(:\d{2})?$/);
    const hint = 'חיפוש בתפילות שנטענו בלבד — יש תפילות קודמות שטרם נטענו';

    // 2. Поиск.
    await search('ערבית');
    await until(async () => { const r = await rows(); return r.length === 1 && r[0].startsWith('ערבית, '); }, '«ערבית» — не одна строка');
    await expectVisibleText(hint);

    await search('23 בספט');
    await until(async () => { const g = await groups(); return g.length === 1 && g[0].includes('23 בספט'); }, '«23 בספט» — не одна группа');

    await search('תשרי');
    await until(async () => (await rows()).length > 0, '«תשרי» — нет строк');

    await search('י״ב');
    await until(async () => { const g = await groups(); return g.length === 1 && g[0].includes('י״ב תשרי'); }, '«י״ב» — не группа «י״ב תשרי»');

    await search('יב');
    await until(async () => { const g = await groups(); return g.length === 1 && g[0].includes('י״ב תשרי'); }, '«יב» — не группа «י״ב תשרי»');

    await search('zzzqq');
    await expectVisibleText('לא נמצאו תפילות שמתאימות ל״zzzqq״.');
    expect((await rows()).length).toBe(0);

    await search('');
    await until(async () => (await rows()).length > 0, 'После очистки поиска нет строк');

    // 3. «טען תפילות קודמות» (внизу списка) — кнопка исчезает после загрузки всех записей.
    await scrollToText('טען תפילות קודמות', 40);
    await tapText('טען תפילות קודמות');
    await until(async () => !(await (await byText('טען תפילות קודמות')).isDisplayed().catch(() => false)), 'Кнопка «טען תפילות קודמות» не исчезла');
    // Кнопки нет и в конце (теперь более длинного) списка.
    const stillThere = await scrollToText('טען תפילות קודמות', 40).then(() => true, () => false);
    expect(stillThere).toBe(false);
  });
});
